/**
 * cn — eigen mini-implementatie van het "classnames"-patroon.
 * Geen clsx, geen tailwind-merge: nul dependencies.
 *
 *   cn("pxui-btn", isPrimary && "pxui-btn-primary", { "is-open": open })
 */
export type ClassValue =
  | string
  | number
  | bigint
  | null
  | undefined
  | false
  | ClassValue[]
  | { [key: string]: unknown };

export function cn(...inputs: ClassValue[]): string {
  const out: string[] = [];

  const walk = (value: ClassValue): void => {
    if (!value) return;
    if (typeof value === "string" || typeof value === "number") {
      out.push(String(value));
      return;
    }
    if (Array.isArray(value)) {
      for (const item of value) walk(item);
      return;
    }
    if (typeof value === "object") {
      for (const key in value) {
        if ((value as Record<string, unknown>)[key]) out.push(key);
      }
    }
  };

  for (const input of inputs) walk(input);

  // Dedupe met behoud van volgorde.
  return Array.from(new Set(out.join(" ").split(/\s+/).filter(Boolean))).join(" ");
}

/**
 * variants — eigen mini-implementatie van het "class variance"-patroon.
 * Geen cva. Bouwt een klassenreeks op basis van props.
 *
 *   const button = variants({
 *     base: "pxui-btn",
 *     variants: {
 *       variant: { primary: "pxui-btn-primary", ghost: "pxui-btn-ghost" },
 *       size:    { sm: "pxui-btn-sm", md: "", lg: "pxui-btn-lg" },
 *     },
 *     defaultVariants: { variant: "primary", size: "md" },
 *   });
 *
 *   button({ variant: "ghost" })  // -> "pxui-btn pxui-btn-ghost"
 */
import { cn, type ClassValue } from "./cn";

type VariantShape = Record<string, Record<string, ClassValue>>;

type VariantProps<V extends VariantShape> = {
  /** Naam van de variant, of een boolean voor true/false-varianten. */
  [K in keyof V]?: keyof V[K] | boolean | null | undefined;
};

export interface VariantConfig<V extends VariantShape> {
  base?: ClassValue;
  variants?: V;
  defaultVariants?: VariantProps<V>;
  compoundVariants?: Array<VariantProps<V> & { class: ClassValue }>;
}

export type VariantsFn<V extends VariantShape> = (
  props?: VariantProps<V> & { className?: ClassValue }
) => string;

export function variants<V extends VariantShape>(config: VariantConfig<V>): VariantsFn<V> {
  const { base, variants: map = {} as V, defaultVariants = {}, compoundVariants = [] } = config;

  return (props = {}) => {
    const { className, ...rest } = props as Record<string, unknown>;
    const resolved: Record<string, unknown> = { ...defaultVariants, ...stripUndefined(rest) };
    const classes: ClassValue[] = [base];

    for (const key in map) {
      const value = resolved[key];
      if (value == null) continue;
      const group = map[key];
      const picked = group[String(value)];
      if (picked) classes.push(picked);
    }

    for (const compound of compoundVariants) {
      const { class: extra, ...conditions } = compound as Record<string, unknown> & { class: ClassValue };
      const matches = Object.keys(conditions).every(
        (key) => String(resolved[key]) === String((conditions as Record<string, unknown>)[key])
      );
      if (matches) classes.push(extra);
    }

    classes.push(className as ClassValue);
    return cn(...classes);
  };
}

function stripUndefined(obj: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const key in obj) if (obj[key] !== undefined) out[key] = obj[key];
  return out;
}

export type { VariantProps };

"use client";
/**
 * Slot — eigen implementatie van het `asChild`-patroon (zoals Radix Slot,
 * maar volledig zelf geschreven). Rendert het enige child-element en
 * voegt de props van de wrapper samen met die van het child.
 */
import * as React from "react";
import { cn } from "./cn";

export interface SlotProps extends React.HTMLAttributes<HTMLElement> {
  children?: React.ReactNode;
}

export const Slot = React.forwardRef<HTMLElement, SlotProps>(function Slot(
  { children, ...slotProps },
  ref
) {
  if (!React.isValidElement(children)) return null;
  const child = children as React.ReactElement<Record<string, unknown>>;

  return React.cloneElement(child, {
    ...mergeProps(slotProps as Record<string, unknown>, child.props),
    ref: composeRefs(ref, (child as unknown as { ref?: React.Ref<HTMLElement> }).ref),
  } as Record<string, unknown>);
});

function mergeProps(
  slotProps: Record<string, unknown>,
  childProps: Record<string, unknown>
): Record<string, unknown> {
  const merged: Record<string, unknown> = { ...slotProps, ...childProps };

  for (const key in slotProps) {
    const slotValue = slotProps[key];
    const childValue = childProps[key];

    if (/^on[A-Z]/.test(key) && typeof slotValue === "function" && typeof childValue === "function") {
      merged[key] = (...args: unknown[]) => {
        (childValue as (...a: unknown[]) => void)(...args);
        (slotValue as (...a: unknown[]) => void)(...args);
      };
    } else if (key === "style") {
      merged[key] = { ...(slotValue as object), ...(childValue as object) };
    } else if (key === "className") {
      merged[key] = cn(slotValue as string, childValue as string);
    }
  }

  return merged;
}

export function composeRefs<T>(...refs: Array<React.Ref<T> | undefined>) {
  return (node: T) => {
    for (const ref of refs) {
      if (typeof ref === "function") ref(node);
      else if (ref && typeof ref === "object") (ref as React.MutableRefObject<T>).current = node;
    }
  };
}

"use client";
import * as React from "react";

/** useLayoutEffect dat niet klaagt tijdens server-rendering. */
export const useIsoLayoutEffect =
  typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect;

/** Stabiele client-check (voorkomt hydration-mismatch bij portals). */
export function useMounted(): boolean {
  const [mounted, setMounted] = React.useState(false);
  React.useEffect(() => setMounted(true), []);
  return mounted;
}

/**
 * Werkt zowel controlled (`value` + `onChange`) als uncontrolled
 * (`defaultValue`). Elke interactieve component in ProjectX UI gebruikt dit.
 */
export function useControllableState<T>(options: {
  value?: T;
  defaultValue: T;
  onChange?: (value: T) => void;
}): [T, (next: T | ((prev: T) => T)) => void] {
  const { value, defaultValue, onChange } = options;
  const isControlled = value !== undefined;
  const [internal, setInternal] = React.useState<T>(defaultValue);
  const current = isControlled ? (value as T) : internal;

  const onChangeRef = React.useRef(onChange);
  useIsoLayoutEffect(() => {
    onChangeRef.current = onChange;
  });

  const setValue = React.useCallback(
    (next: T | ((prev: T) => T)) => {
      const resolved =
        typeof next === "function" ? (next as (prev: T) => T)(currentRef.current) : next;
      if (!isControlled) setInternal(resolved);
      onChangeRef.current?.(resolved);
    },
    [isControlled]
  );

  const currentRef = React.useRef(current);
  currentRef.current = current;

  return [current, setValue];
}

/** Roept `handler` aan bij een klik buiten alle meegegeven refs. */
export function useOutsideClick(
  refs: Array<React.RefObject<HTMLElement | null>>,
  handler: (event: MouseEvent | TouchEvent) => void,
  enabled = true
): void {
  const handlerRef = React.useRef(handler);
  handlerRef.current = handler;

  React.useEffect(() => {
    if (!enabled) return;
    const listener = (event: MouseEvent | TouchEvent) => {
      const target = event.target as Node | null;
      if (!target || !document.contains(target)) return;
      for (const ref of refs) {
        if (ref.current && ref.current.contains(target)) return;
      }
      handlerRef.current(event);
    };
    document.addEventListener("mousedown", listener, true);
    document.addEventListener("touchstart", listener, true);
    return () => {
      document.removeEventListener("mousedown", listener, true);
      document.removeEventListener("touchstart", listener, true);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled, ...refs]);
}

/** Escape-toets afhandelen (capture, zodat geneste lagen eerst sluiten). */
export function useEscapeKey(handler: () => void, enabled = true): void {
  const handlerRef = React.useRef(handler);
  handlerRef.current = handler;

  React.useEffect(() => {
    if (!enabled) return;
    const listener = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.stopPropagation();
        handlerRef.current();
      }
    };
    document.addEventListener("keydown", listener, true);
    return () => document.removeEventListener("keydown", listener, true);
  }, [enabled]);
}

/** Blokkeert scrollen van de pagina zolang een overlay open staat. */
export function useLockScroll(enabled: boolean): void {
  React.useEffect(() => {
    if (!enabled) return;
    const { overflow, paddingRight } = document.body.style;
    const gap = window.innerWidth - document.documentElement.clientWidth;
    document.body.style.overflow = "hidden";
    if (gap > 0) document.body.style.paddingRight = `${gap}px`;
    return () => {
      document.body.style.overflow = overflow;
      document.body.style.paddingRight = paddingRight;
    };
  }, [enabled]);
}

const FOCUSABLE = [
  "a[href]",
  "button:not([disabled])",
  "input:not([disabled]):not([type='hidden'])",
  "select:not([disabled])",
  "textarea:not([disabled])",
  "[tabindex]:not([tabindex='-1'])",
].join(",");

/** Houdt focus binnen een container (dialog, drawer) en herstelt hem daarna. */
export function useFocusTrap(
  ref: React.RefObject<HTMLElement | null>,
  enabled: boolean
): void {
  React.useEffect(() => {
    if (!enabled || !ref.current) return;
    const node = ref.current;
    const previous = document.activeElement as HTMLElement | null;

    const focusables = () => Array.from(node.querySelectorAll<HTMLElement>(FOCUSABLE));
    const first = focusables()[0];
    (first ?? node).focus({ preventScroll: true });

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Tab") return;
      const items = focusables();
      if (items.length === 0) {
        event.preventDefault();
        return;
      }
      const firstItem = items[0];
      const lastItem = items[items.length - 1];
      if (event.shiftKey && document.activeElement === firstItem) {
        event.preventDefault();
        lastItem.focus();
      } else if (!event.shiftKey && document.activeElement === lastItem) {
        event.preventDefault();
        firstItem.focus();
      }
    };

    node.addEventListener("keydown", onKeyDown);
    return () => {
      node.removeEventListener("keydown", onKeyDown);
      previous?.focus?.({ preventScroll: true });
    };
  }, [enabled, ref]);
}

/** Pijltjes-navigatie voor menu's, listboxen en tabs. */
export function useRovingIndex(count: number, initial = -1) {
  const [index, setIndex] = React.useState(initial);

  const move = React.useCallback(
    (delta: number) => {
      setIndex((prev) => {
        if (count === 0) return -1;
        const next = prev + delta;
        if (next < 0) return count - 1;
        if (next >= count) return 0;
        return next;
      });
    },
    [count]
  );

  return { index, setIndex, move };
}

/** Kopieert tekst naar het klembord en houdt kort een "gekopieerd"-status bij. */
export function useCopyToClipboard(timeout = 1600) {
  const [copied, setCopied] = React.useState(false);

  const copy = React.useCallback(
    async (text: string) => {
      try {
        await navigator.clipboard.writeText(text);
        setCopied(true);
        window.setTimeout(() => setCopied(false), timeout);
        return true;
      } catch {
        return false;
      }
    },
    [timeout]
  );

  return { copied, copy };
}

"use client";
/**
 * Positionering voor zwevende lagen (dropdown, popover, select, tooltip,
 * combobox). Eigen implementatie — geen Floating UI / Popper.
 *
 * Ondersteunt: side + align, offset, automatische flip bij te weinig ruimte,
 * clampen binnen de viewport, breedte gelijk aan de anchor, en herberekenen
 * bij scroll/resize.
 */
import * as React from "react";
import { useIsoLayoutEffect } from "./hooks";

export type Side = "top" | "right" | "bottom" | "left";
export type Align = "start" | "center" | "end";

export interface AnchorOptions {
  side?: Side;
  align?: Align;
  /** Afstand tussen anchor en laag, in px. */
  offset?: number;
  /** Minimale marge tot de rand van het scherm. */
  padding?: number;
  /** Laag krijgt exact de breedte van de anchor (select, combobox). */
  matchWidth?: boolean;
  /** Laag krijgt minimaal de breedte van de anchor. */
  minWidth?: boolean;
}

export interface AnchorPosition {
  style: React.CSSProperties;
  side: Side;
  align: Align;
  ready: boolean;
}

export function useAnchorPosition(
  anchorRef: React.RefObject<HTMLElement | null>,
  floatingRef: React.RefObject<HTMLElement | null>,
  open: boolean,
  options: AnchorOptions = {}
): AnchorPosition {
  const {
    side = "bottom",
    align = "start",
    offset = 6,
    padding = 8,
    matchWidth = false,
    minWidth = false,
  } = options;

  const [position, setPosition] = React.useState<AnchorPosition>({
    style: { position: "fixed", top: 0, left: 0, opacity: 0, visibility: "hidden" },
    side,
    align,
    ready: false,
  });

  const compute = React.useCallback(() => {
    const anchor = anchorRef.current;
    const floating = floatingRef.current;
    if (!anchor || !floating) return;

    const a = anchor.getBoundingClientRect();
    const f = floating.getBoundingClientRect();
    const vw = document.documentElement.clientWidth;
    const vh = document.documentElement.clientHeight;

    const space = {
      top: a.top - padding,
      bottom: vh - a.bottom - padding,
      left: a.left - padding,
      right: vw - a.right - padding,
    };

    // Flip wanneer er aan de gewenste kant te weinig ruimte is.
    let usedSide: Side = side;
    const needed = side === "top" || side === "bottom" ? f.height + offset : f.width + offset;
    if (space[side] < needed) {
      const opposite: Record<Side, Side> = { top: "bottom", bottom: "top", left: "right", right: "left" };
      if (space[opposite[side]] > space[side]) usedSide = opposite[side];
    }

    const width = matchWidth ? a.width : minWidth ? Math.max(a.width, f.width) : f.width;

    let left = 0;
    let top = 0;

    if (usedSide === "bottom" || usedSide === "top") {
      top = usedSide === "bottom" ? a.bottom + offset : a.top - offset - f.height;
      left =
        align === "start" ? a.left : align === "end" ? a.right - width : a.left + a.width / 2 - width / 2;
    } else {
      left = usedSide === "right" ? a.right + offset : a.left - offset - width;
      top =
        align === "start" ? a.top : align === "end" ? a.bottom - f.height : a.top + a.height / 2 - f.height / 2;
    }

    // Binnen beeld houden.
    left = clamp(left, padding, Math.max(padding, vw - width - padding));
    top = clamp(top, padding, Math.max(padding, vh - f.height - padding));

    // Maximale hoogte zodat lange menu's kunnen scrollen in plaats van afgesneden worden.
    const maxHeight =
      usedSide === "bottom"
        ? Math.max(120, vh - (a.bottom + offset) - padding)
        : usedSide === "top"
          ? Math.max(120, a.top - offset - padding)
          : Math.max(120, vh - 2 * padding);

    setPosition({
      style: {
        position: "fixed",
        visibility: "visible",
        top: Math.round(top),
        left: Math.round(left),
        ...(matchWidth || minWidth ? { [matchWidth ? "width" : "minWidth"]: Math.round(width) } : {}),
        maxHeight: Math.round(maxHeight),
      },
      side: usedSide,
      align,
      ready: true,
    });
  }, [anchorRef, floatingRef, side, align, offset, padding, matchWidth, minWidth]);

  useIsoLayoutEffect(() => {
    if (!open) {
      setPosition((p) => ({
        ...p,
        ready: false,
        style: { ...p.style, opacity: 0, visibility: "hidden" },
      }));
      return;
    }

    // De zwevende laag zit in een portal en is soms pas een frame later
    // gemonteerd; daarom proberen we het opnieuw tot beide elementen bestaan.
    const onChange = () => compute();
    const observer = typeof ResizeObserver !== "undefined" ? new ResizeObserver(onChange) : null;

    let frame = 0;
    let attempts = 0;
    const attach = () => {
      if (anchorRef.current && floatingRef.current) {
        compute();
        observer?.observe(floatingRef.current);
        observer?.observe(anchorRef.current);
        return;
      }
      if (attempts < 20) {
        attempts += 1;
        frame = requestAnimationFrame(attach);
      }
    };
    attach();

    window.addEventListener("scroll", onChange, true);
    window.addEventListener("resize", onChange);

    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener("scroll", onChange, true);
      window.removeEventListener("resize", onChange);
      observer?.disconnect();
    };
  }, [open, compute, anchorRef, floatingRef]);

  return position;
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

"use client";
/** Portal — rendert children in document.body (of een eigen container). */
import * as React from "react";
import { createPortal } from "react-dom";
import { useMounted } from "./hooks";

export function Portal({
  children,
  container,
}: {
  children: React.ReactNode;
  container?: Element | null;
}) {
  const mounted = useMounted();
  if (!mounted) return null;
  return createPortal(children, container ?? document.body);
}

import * as React from "react";
import { ICONS, type IconName } from "./icons";

export interface IconProps extends Omit<React.SVGProps<SVGSVGElement>, "name"> {
  name: IconName;
  size?: number | string;
  strokeWidth?: number;
}

/**
 * Icon — rendert één glyph uit de eigen ProjectX UI icon set.
 * Kleur volgt `currentColor`, dus elk component stuurt de kleur via CSS.
 */
export const Icon = React.forwardRef<SVGSVGElement, IconProps>(function Icon(
  { name, size = 16, strokeWidth = 2, className, ...rest },
  ref
) {
  const d = ICONS[name];
  if (!d) return null;

  return (
    <svg
      ref={ref}
      className={className}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
      {...rest}
    >
      {d.split(" M").map((segment, index) => (
        <path key={index} d={index === 0 ? segment : `M${segment}`} />
      ))}
    </svg>
  );
});

export { ICONS, ICON_NAMES } from "./icons";
export type { IconName } from "./icons";

/* ============================================================
   ProjectX UI — Design tokens
   Bron: het ProjectX UI-design (Claude Design).
   ALLE kleuren komen uit dit bestand. Componenten gebruiken
   NOOIT een hardcoded kleur — altijd var(--...).
   ============================================================ */

:root {
  /* ---------- Accent (teal) ---------- */
  --accent: #0d9488;
  --accent-hover: #0f766e;
  --accent-active: #115e59;
  --accent-fg: #ffffff;
  --accent-tint: #f0fdfa;
  --accent-tint-2: #ccfbf1;
  --accent-border: #99f6e4;

  /* ---------- Neutraal (slate) — light ---------- */
  --bg: #f7f8fa;
  --bg-grad: radial-gradient(120% 120% at 50% 0%, #ffffff 0%, #f4f6f8 60%, #eef1f4 100%);
  --surface: #ffffff;
  --surface-2: #f9fafb;
  --surface-3: #f1f3f5;
  --surface-hover: #f4f6f8;
  --border: #e7e9ee;
  --border-strong: #d6dae1;
  --text: #0f1729;
  --text-2: #475063;
  --text-3: #8a93a6;
  --text-inv: #ffffff;
  --overlay: rgba(10, 13, 18, .45);

  /* ---------- Status ---------- */
  --green: #16a34a;
  --green-tint: #f0fdf4;
  --green-border: #bbf7d0;
  --amber: #d97706;
  --amber-tint: #fffbeb;
  --amber-border: #fde68a;
  --red: #dc2626;
  --red-tint: #fef2f2;
  --red-border: #fecaca;
  --blue: #2563eb;
  --blue-tint: #eff6ff;
  --blue-border: #bfdbfe;
  --violet: #7c3aed;
  --violet-tint: #f5f3ff;
  --violet-border: #ddd6fe;

  /* ---------- Datavisualisatie ---------- */
  --chart-1: var(--accent);
  --chart-2: var(--blue);
  --chart-3: var(--violet);
  --chart-4: var(--amber);
  --chart-5: var(--green);
  --chart-6: var(--red);

  /* ---------- Radius ---------- */
  --r-xs: 6px;
  --r-sm: 8px;
  --r-md: 11px;
  --r-lg: 14px;
  --r-xl: 20px;
  --r-2xl: 26px;
  --r-full: 999px;

  /* ---------- Shadow ---------- */
  --sh-xs: 0 1px 2px rgba(16, 23, 41, .05);
  --sh-sm: 0 1px 2px rgba(16, 23, 41, .06), 0 1px 1px rgba(16, 23, 41, .04);
  --sh-md: 0 4px 12px rgba(16, 23, 41, .07), 0 1px 3px rgba(16, 23, 41, .05);
  --sh-lg: 0 12px 32px rgba(16, 23, 41, .10), 0 4px 10px rgba(16, 23, 41, .05);
  --sh-xl: 0 24px 60px rgba(16, 23, 41, .16), 0 8px 18px rgba(16, 23, 41, .07);
  --ring: 0 0 0 3.5px color-mix(in srgb, var(--accent) 22%, transparent);
  --ring-red: 0 0 0 3.5px color-mix(in srgb, var(--red) 22%, transparent);

  /* ---------- Layout ---------- */
  --sidebar-w: 256px;
  --topbar-h: 64px;
  --maxw: 1160px;

  /* ---------- Typografie ---------- */
  --font: "Hanken Grotesk", -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;
  --mono: "JetBrains Mono", ui-monospace, "SF Mono", Menlo, monospace;

  --fs-xs: 11.5px;
  --fs-sm: 12.5px;
  --fs-base: 14px;
  --fs-md: 15px;
  --fs-lg: 16px;
  --fs-xl: 20px;
  --fs-2xl: 26px;
  --fs-3xl: 34px;

  /* ---------- Motion ---------- */
  --ease: cubic-bezier(.4, 0, .2, 1);
  --ease-out: cubic-bezier(.2, .9, .3, 1);
  --ease-pop: cubic-bezier(.2, .9, .3, 1.2);
  --dur-fast: .12s;
  --dur: .18s;
  --dur-slow: .28s;

  /* ---------- Z-index schaal ---------- */
  --z-sticky: 20;
  --z-drawer: 70;
  --z-overlay: 100;
  --z-popover: 2000;
  --z-toast: 2200;

  /* ---------- Sidebar, donkere variant ---------- */
  /* Volledig afgeleid van de bestaande tokens: een donkere, teal-getinte rail
     die ook in lichtmodus werkt (zoals in het planningsdesign). */
  --sidebar-ink: color-mix(in srgb, var(--accent-active) 20%, var(--text));
  --sidebar-ink-2: color-mix(in srgb, var(--accent-active) 32%, var(--text));
  --sidebar-ink-border: color-mix(in srgb, var(--text-inv) 10%, transparent);
  --sidebar-ink-text: color-mix(in srgb, var(--text-inv) 72%, transparent);
  --sidebar-ink-strong: var(--text-inv);
  --sidebar-ink-dim: color-mix(in srgb, var(--text-inv) 48%, transparent);
  --sidebar-ink-hover: color-mix(in srgb, var(--text-inv) 8%, transparent);
  --sidebar-ink-active: color-mix(in srgb, var(--accent) 26%, transparent);
  --sidebar-ink-accent: var(--accent-tint-2);

  /* ---------- Dichtheid ----------
