/* ------------------------------------------------------------
   Tailwind v4 draait puur als CSS-engine (reset + utilities).
   Deze @theme-mapping maakt dezelfde tokens beschikbaar als
   utilities (bg-accent, text-text-2, rounded-lg, ...) voor NIEUWE
   markup. De componenten zelf gebruiken hun eigen .pxui-* klassen.
   ------------------------------------------------------------ */
@theme {
  --color-accent: #0d9488;
  --color-accent-hover: #0f766e;
  --color-accent-active: #115e59;
  --color-accent-fg: #ffffff;
  --color-accent-tint: #f0fdfa;
  --color-accent-tint-2: #ccfbf1;
  --color-accent-border: #99f6e4;
  --color-surface: #ffffff;
  --color-surface-2: #f9fafb;
  --color-surface-3: #f1f3f5;
  --color-border: #e7e9ee;
  --color-border-strong: #d6dae1;
  --color-text: #0f1729;
  --color-text-2: #475063;
  --color-text-3: #8a93a6;
  --color-green: #16a34a;
  --color-amber: #d97706;
  --color-red: #dc2626;
  --color-blue: #2563eb;
  --color-violet: #7c3aed;
  --radius-xs: 6px;
  --radius-sm: 8px;
  --radius-md: 11px;
  --radius-lg: 14px;
  --radius-xl: 20px;
  --font-sans: "Hanken Grotesk", -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, "SF Mono", Menlo, monospace;
}

/* ============================================================
   ProjectX UI — Base laag
   Typografie, body-styling, scrollbars, gedeelde animaties.
   ============================================================ */

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  font-feature-settings: "ss01", "cv01";
}

button, input, select, textarea { font-family: inherit; }
::selection { background: var(--accent-tint-2); color: var(--text); }

*::-webkit-scrollbar { width: 10px; height: 10px; }
*::-webkit-scrollbar-thumb {
  background: var(--border-strong); border-radius: var(--r-full);
  border: 3px solid transparent; background-clip: content-box;
}
*::-webkit-scrollbar-thumb:hover { background: var(--text-3); background-clip: content-box; }
*::-webkit-scrollbar-track { background: transparent; }

h1, h2, h3, h4 {
  margin: 0; font-weight: 650; letter-spacing: -0.02em;
  line-height: 1.12; color: var(--text);
}
p { margin: 0; line-height: 1.6; color: var(--text-2); }

/* ---------- Typografie-helpers ---------- */
.pxui-display { font-size: var(--fs-3xl); font-weight: 700; letter-spacing: -0.03em; line-height: 1.1; }
.pxui-h1 { font-size: var(--fs-2xl); font-weight: 650; letter-spacing: -0.02em; }
.pxui-h2 { font-size: var(--fs-xl); font-weight: 650; letter-spacing: -0.02em; }
.pxui-h3 { font-size: var(--fs-lg); font-weight: 650; letter-spacing: -0.02em; }
.pxui-eyebrow {
  font-size: 12px; font-weight: 650; letter-spacing: .09em;
  text-transform: uppercase; color: var(--text-3);
}
.pxui-muted { color: var(--text-2); }
.pxui-subtle { color: var(--text-3); }
.pxui-mono { font-family: var(--mono); font-feature-settings: normal; }
.pxui-lead { font-size: var(--fs-md); color: var(--text-2); line-height: 1.6; }

/* ---------- Gedeelde animaties ---------- */
@keyframes pxui-fade-in { from { opacity: 0; transform: translateY(7px); } to { opacity: 1; transform: none; } }
@keyframes pxui-pop-in { from { opacity: 0; transform: scale(.97); } to { opacity: 1; transform: none; } }
@keyframes pxui-overlay-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes pxui-spin { to { transform: rotate(360deg); } }
@keyframes pxui-shimmer { to { background-position: -200% 0; } }
@keyframes pxui-menu-in { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: none; } }

.pxui-fade-in { animation: pxui-fade-in .35s var(--ease) both; }
.pxui-pop-in { animation: pxui-pop-in var(--dur-slow) var(--ease-pop) both; }

/* ---------- Focus ---------- */
.pxui-focus-ring:focus-visible { outline: none; box-shadow: var(--ring); }

/* ---------- Screenreader-only ---------- */
.pxui-sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .001ms !important;
  }
}
